from html.parser import HTMLParser
from pathlib import Path
from html import unescape
import subprocess, tempfile

path = Path('/home/lijian/project/work/pzx/_42_h3pack_TAP_Bridge_Network_Design.html')
text = path.read_text(encoding='utf-8')

class Validator(HTMLParser):
    void = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack = []
        self.errors = []
        self.in_code = False
        self.in_pre = False
        self.buf = []
        self.blocks = []
    def handle_starttag(self, tag, attrs):
        if tag not in self.void:
            self.stack.append(tag)
        if tag == 'pre': self.in_pre = True
        if tag == 'code' and self.in_pre:
            self.in_code = True
            self.buf = []
    def handle_endtag(self, tag):
        if tag == 'code' and self.in_code:
            self.blocks.append(''.join(self.buf))
            self.in_code = False
        if tag == 'pre': self.in_pre = False
        if tag in self.void: return
        if not self.stack:
            self.errors.append(f'unexpected closing </{tag}>')
            return
        if self.stack[-1] != tag:
            self.errors.append(f'closing </{tag}> while <{self.stack[-1]}> is open')
            if tag in self.stack:
                while self.stack and self.stack[-1] != tag:
                    self.stack.pop()
                if self.stack: self.stack.pop()
        else:
            self.stack.pop()
    def handle_data(self, data):
        if self.in_code: self.buf.append(data)

v = Validator(); v.feed(text); v.close()
if v.stack: v.errors.append('unclosed: ' + ', '.join(v.stack[-10:]))
if v.errors:
    raise SystemExit('HTML structure errors:\n' + '\n'.join(v.errors[:20]))

scripts = [b for b in v.blocks if b.startswith('#!/usr/bin/env bash')]
for i, script in enumerate(scripts, 1):
