        f.write(script)
        name = f.name
    result = subprocess.run(['bash', '-n', name], capture_output=True, text=True)
    Path(name).unlink()
    if result.returncode:
        raise SystemExit(f'Bash block {i} failed syntax check:\n{result.stderr}')

required = ['192.168.1.201/32', 'ip neigh add proxy', 'br-qemu', 'host IP/default route unchanged']
missing = [s for s in required if s not in text]
if missing:
    raise SystemExit('Missing required content: ' + ', '.join(missing))
print(f'OK: HTML structure valid; {len(scripts)} shell scripts pass bash -n; required routed-network content present.')
